-- Ninth private chapter: Black Clover fanart. Preserve existing catalog, wallets, copies, claims and visibility.
insert into jj_collect.catalog(id,data) values('nu-241','{"id": "nu-241", "number": 241, "name_es": "El grimorio que me eligió", "name_en": "The Grimoire That Chose Me", "character": "jesus", "theme": "fantasia", "tags": ["black-clover"], "rarity": 0, "sell": 4, "scrap": 1, "craft": 8, "dedication_es": "Me gusta pensar que incluso un comienzo inesperado puede llevarnos a una historia bonita.", "dedication_en": "I love thinking that even an unexpected beginning can lead us to a lovely story.", "art": 0, "collection": "noveno-universo"}'::jsonb) on conflict(id) do nothing;
insert into jj_collect.catalog(id,data) values('nu-242','{"id": "nu-242", "number": 242, "name_es": "Tu primera esfera de agua", "name_en": "Your First Water Sphere", "character": "julisa", "theme": "fantasia", "tags": ["black-clover"], "rarity": 0, "sell": 4, "scrap": 1, "craft": 8, "dedication_es": "Quise imaginarte descubriendo algo nuevo, con espacio para equivocarte y volver a sonreír.", "dedication_en": "I wanted to imagine you discovering something new, with room to make mistakes and smile again.", "art": 1, "collection": "noveno-universo"}'::jsonb) on conflict(id) do nothing;
insert into jj_collect.catalog(id,data) values('nu-243','{"id": "nu-243", "number": 243, "name_es": "Nuestro lugar entre los Toros", "name_en": "Our Place Among the Bulls", "character": "duo", "theme": "fantasia", "tags": ["black-clover"], "rarity": 0, "sell": 4, "scrap": 1, "craft": 8, "dedication_es": "Si esta base fuera nuestra próxima parada, buscaría contigo el rincón más cómodo para conversar.", "dedication_en": "If this base were our next stop, I would find the coziest corner to talk with you.", "art": 2, "collection": "noveno-universo"}'::jsonb) on conflict(id) do nothing;
insert into jj_collect.catalog(id,data) values('nu-244','{"id": "nu-244", "number": 244, "name_es": "Una espada, muchos intentos", "name_en": "One Sword, Many Attempts", "character": "jesus", "theme": "fantasia", "tags": ["black-clover"], "rarity": 0, "sell": 4, "scrap": 1, "craft": 8, "dedication_es": "No necesito aprender todo de golpe; también quiero disfrutar los pequeños avances que pueda contarte.", "dedication_en": "I do not need to learn everything at once; I want to enjoy the little progress I can tell you about too.", "art": 3, "collection": "noveno-universo"}'::jsonb) on conflict(id) do nothing;
insert into jj_collect.catalog(id,data) values('nu-245','{"id": "nu-245", "number": 245, "name_es": "El agua encuentra su forma", "name_en": "Water Finds Its Shape", "character": "julisa", "theme": "fantasia", "tags": ["black-clover"], "rarity": 0, "sell": 4, "scrap": 1, "craft": 8, "dedication_es": "Hay algo bonito en descubrir tu manera de hacer las cosas, incluso cuando toma tiempo.", "dedication_en": "There is something lovely about discovering your own way of doing things, even when it takes time.", "art": 4, "collection": "noveno-universo"}'::jsonb) on conflict(id) do nothing;
insert into jj_collect.catalog(id,data) values('nu-246','{"id": "nu-246", "number": 246, "name_es": "Pan para dos en Hage", "name_en": "Bread for Two in Hage", "character": "duo", "theme": "fantasia", "tags": ["black-clover"], "rarity": 0, "sell": 4, "scrap": 1, "craft": 8, "dedication_es": "Entre misiones y grimorios, seguiría guardando una pausa para compartir un antojo contigo.", "dedication_en": "Between missions and grimoires, I would still save a pause to share a little treat with you.", "art": 5, "collection": "noveno-universo"}'::jsonb) on conflict(id) do nothing;
insert into jj_collect.catalog(id,data) values('nu-247','{"id": "nu-247", "number": 247, "name_es": "Mi capa de Toro Negro", "name_en": "My Black Bull Cloak", "character": "jesus", "theme": "fantasia", "tags": ["black-clover"], "rarity": 0, "sell": 4, "scrap": 1, "craft": 8, "dedication_es": "Una capa puede cambiar esta aventura; las ganas de hacerte reír ya venían conmigo.", "dedication_en": "A cloak can change this adventure; my wish to make you laugh was already with me.", "art": 6, "collection": "noveno-universo"}'::jsonb) on conflict(id) do nothing;
