insert into jj_collect.catalog(id,data) values('nu-250','{"id": "nu-250", "number": 250, "name_es": "Un visitante en mi cabeza", "name_en": "A Visitor on My Head", "character": "jesus", "theme": "fantasia", "tags": ["black-clover"], "rarity": 0, "sell": 4, "scrap": 1, "craft": 8, "dedication_es": "Si este pequeño compañero decide despeinarme, al menos tendremos una nueva razón para reír.", "dedication_en": "If this little companion decides to mess up my hair, at least we will have another reason to laugh.", "art": 9, "collection": "noveno-universo"}'::jsonb) on conflict(id) do nothing;
insert into jj_collect.catalog(id,data) values('nu-251','{"id": "nu-251", "number": 251, "name_es": "Flores bajo tu lluvia", "name_en": "Flowers Beneath Your Rain", "character": "julisa", "theme": "fantasia", "tags": ["black-clover"], "rarity": 0, "sell": 4, "scrap": 1, "craft": 8, "dedication_es": "Esta escena me recuerda que cuidar también puede ser un gesto sencillo y constante.", "dedication_en": "This scene reminds me that caring can be a simple, steady gesture too.", "art": 10, "collection": "noveno-universo"}'::jsonb) on conflict(id) do nothing;
insert into jj_collect.catalog(id,data) values('nu-252','{"id": "nu-252", "number": 252, "name_es": "Estrellas sobre la base", "name_en": "Stars Above the Base", "character": "duo", "theme": "fantasia", "tags": ["black-clover"], "rarity": 0, "sell": 4, "scrap": 1, "craft": 8, "dedication_es": "Después del ruido del día, me gustaría compartir contigo un cielo que podamos mirar sin prisa.", "dedication_en": "After a noisy day, I would love to share a sky we can watch without hurry.", "art": 11, "collection": "noveno-universo"}'::jsonb) on conflict(id) do nothing;
insert into jj_collect.catalog(id,data) values('nu-253','{"id": "nu-253", "number": 253, "name_es": "El filo de la antimagia", "name_en": "The Edge of Anti-Magic", "character": "jesus", "theme": "fantasia", "tags": ["black-clover"], "rarity": 1, "sell": 35, "scrap": 4, "craft": 24, "dedication_es": "En este mundo puedo romper hechizos; en el nuestro prefiero aprender a entender lo que sentimos.", "dedication_en": "In this world I can break spells; in ours I would rather learn to understand what we feel.", "art": 12, "collection": "noveno-universo"}'::jsonb) on conflict(id) do nothing;
insert into jj_collect.catalog(id,data) values('nu-254','{"id": "nu-254", "number": 254, "name_es": "El dragón de tus mareas", "name_en": "The Dragon of Your Tides", "character": "julisa", "theme": "fantasia", "tags": ["black-clover"], "rarity": 1, "sell": 35, "scrap": 4, "craft": 24, "dedication_es": "Te dibujé entre olas enormes sin olvidar la sonrisa que quería guardar en esta carta.", "dedication_en": "I pictured you among enormous waves without forgetting the smile I wanted to keep in this card.", "art": 13, "collection": "noveno-universo"}'::jsonb) on conflict(id) do nothing;
insert into jj_collect.catalog(id,data) values('nu-255','{"id": "nu-255", "number": 255, "name_es": "Dos capas frente al misterio", "name_en": "Two Cloaks Before the Mystery", "character": "duo", "theme": "fantasia", "tags": ["black-clover"], "rarity": 1, "sell": 35, "scrap": 4, "craft": 24, "dedication_es": "No sabemos qué habrá detrás de esa puerta, pero podemos decidir juntos cuándo cruzarla.", "dedication_en": "We do not know what lies beyond that door, but we can decide together when to cross it.", "art": 14, "collection": "noveno-universo"}'::jsonb) on conflict(id) do nothing;
