insert into jj_collect.catalog(id,data) values('nu-257','{"id": "nu-257", "number": 257, "name_es": "El jardín de tu magia", "name_en": "The Garden of Your Magic", "character": "julisa", "theme": "fantasia", "tags": ["black-clover"], "rarity": 1, "sell": 35, "scrap": 4, "craft": 24, "dedication_es": "Ojalá esta fantasía te deje la calma de un jardín donde puedas quedarte a tu ritmo.", "dedication_en": "I hope this fantasy leaves you with the calm of a garden where you can stay at your own pace.", "art": 16, "collection": "noveno-universo"}'::jsonb) on conflict(id) do nothing;
insert into jj_collect.catalog(id,data) values('nu-258','{"id": "nu-258", "number": 258, "name_es": "Un vuelo sobre Trébol", "name_en": "A Flight Above Clover", "character": "duo", "theme": "fantasia", "tags": ["black-clover"], "rarity": 1, "sell": 35, "scrap": 4, "craft": 24, "dedication_es": "Si pudiéramos ver el reino desde aquí, te preguntaría qué lugar te gustaría conocer primero.", "dedication_en": "If we could see the kingdom from up here, I would ask which place you would love to visit first.", "art": 17, "collection": "noveno-universo"}'::jsonb) on conflict(id) do nothing;
