insert into jj_collect.catalog(id,data) values('nu-260','{"id": "nu-260", "number": 260, "name_es": "Rosas que llevan tu nombre", "name_en": "Roses That Carry Your Name", "character": "julisa", "theme": "fantasia", "tags": ["black-clover"], "rarity": 1, "sell": 35, "scrap": 4, "craft": 24, "dedication_es": "Estas rosas son de fantasía, pero el cariño con el que preparé tu carta sí es mío.", "dedication_en": "These roses are imaginary, but the care with which I made your card is mine.", "art": 19, "collection": "noveno-universo"}'::jsonb) on conflict(id) do nothing;
